"""第一階段三圖只讀自己的結果；頻響答案由原始能量獨立計算。"""
from pathlib import Path
import json
import math
import os
import re
import time
import uuid
from typing import TypedDict

import pytest

from aosr.config.directivity_defaults import load_directivity_defaults
from aosr.config.paths import config_path
from aosr.gui.search_best import BestCache, build_best_view
from aosr.gui.search_view import best_versions
from aosr.gui import search_view
from aosr.reporting.result import SchemeResult, Timings
from aosr.search.store import SearchStore
from tests.engine.test_stage_one_shortlist import _finished
from tests.engine._gui_best_cases import best_result, best_store
from tests.engine.test_gui_stage_one_view import UtcClock
from tests.engine.test_gui_search_view import _snapshot


ABSENT = "第一階段只算 20～300 Hz 有限元素，沒有早期反射，這張圖不適用"
AXES = {"search_octave_24": "舊搜尋軸（每八度 24 點）", "search_octave_48": "搜尋軸（每八度 48 點）", "verification_linear_1hz": "驗證軸（每 1 Hz）"}


def best(store: SearchStore, which: str | None = None, cache: BestCache | None = None) -> dict[str, object]:
    return build_best_view(store.path, which=which, cache=cache or BestCache(),
        directivity=load_directivity_defaults(config_path("directivity_defaults.toml")))


def winner_file(store: SearchStore) -> Path:
    raw = json.loads((store.path / "stage_one_refine.json").read_bytes())
    winner = next(row for row in raw["results"] if row["state"] == "scored" and row["refine_rank"] == 1)
    return store.path / str(winner["result_file"])


class ExpectedCurve(TypedDict):
    role: str
    label: str
    points: list[list[float | None]]


def frequency_from_raw(document: str) -> list[ExpectedCurve]:
    raw = json.loads(document)
    roles = {channel["speaker_id"]: channel["role"] for channel in raw["scheme"]["channel_group"]["channels"]}
    return [{"role": roles[curve["speaker_id"]],
        "label": ("左" if roles[curve["speaker_id"]] == "left" else "右") + "聲道 → 主位",
        "points": [[f, 10 * math.log10(e) if e is not None and e > 0 else None]
            for f, e in zip(curve["primary"]["frequencies_hz"], curve["primary"]["fem_energy"], strict=True)]}
        for curve in raw["curves"]]


@pytest.mark.parametrize("which", [None, "search"])
def test_finished_best_uses_saved_primary_curves_and_axis(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                                        which: str | None) -> None:
    store = _finished(tmp_path, monkeypatch)
    before = _snapshot(store.path)
    _, versions, default = best_versions(store.path)
    raw_refine = json.loads((store.path / "stage_one_refine.json").read_bytes())
    winner = next(row for row in raw_refine["results"] if row["state"] == "scored" and row["refine_rank"] == 1)
    assert default == "refine"
    # 網頁預設看哪一版由伺服器的搜尋頁回應給（search_best.js 照 best_default 載入），跟 best_versions 同一條判法。
    assert search_view.build_search_view(store.path, server_physics="", server_program="").best_default == "refine"
    assert versions["refine"].candidate == str(winner["trial_number"])
    assert versions["refine"].result_file == winner["result_file"]
    status = json.loads(store.status_path.read_bytes())
    target = winner_file(store) if which is None else store.candidate_path(status["best_trial"])
    raw = json.loads(target.read_bytes())
    shown = best(store, which)
    label = "細算第一名" if which is None else "搜尋第一名"
    number = winner["trial_number"] if which is None else status["best_trial"]
    assert shown["title"] == f"目前最佳：{label}／試算 {number}／{AXES[raw['low_frequency_axis']]}"
    frequency = shown["frequency"]
    expected = frequency_from_raw(json.dumps(raw))
    assert isinstance(frequency, dict) and frequency["error"] == ""
    assert frequency["curves"] == expected
    assert frequency["data"] == [raw["curves"][0]["primary"]["frequencies_hz"],
        *[[point[1] for point in curve["points"]] for curve in expected]]
    assert frequency["axis_text"] == AXES[raw["low_frequency_axis"]]
    assert frequency["note"] == raw["wall_assumption_text"] and frequency["furniture_note"] == ""
    assert shown["rfz"] == {"error": "", "absent": ABSENT}
    plan = shown["plan"]
    assert isinstance(plan, dict) and plan["error"] == ""
    assert plan["data"]["room"] == raw["scheme"]["scene"]["room_m"]
    assert {speaker["id"]: speaker["point"] for speaker in plan["data"]["speakers"]} == raw["scheme"]["speakers"]
    assert all(speaker["aim"] is None for speaker in plan["data"]["speakers"])
    assert _snapshot(store.path) == before


@pytest.mark.parametrize("state", ["absent", "selected", "failed", "broken"])
def test_no_ranked_refine_defaults_to_search(tmp_path: Path, monkeypatch: pytest.MonkeyPatch, state: str) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = store.path / "stage_one_refine.json"
    raw = json.loads(target.read_bytes())
    if state == "absent":
        target.unlink()
    elif state == "broken":
        target.write_text("{")
    else:
        raw.update(state=state, results=[])
        target.write_text(json.dumps(raw))
    _, versions, default = best_versions(store.path)
    assert default == "search"
    assert search_view.build_search_view(store.path, server_physics="", server_program="").best_default == "search"
    assert versions["refine"].error.startswith("讀不到：")
    if state != "broken":
        assert versions["refine"].error == "讀不到：尚無細算第一名"
    assert best(store)["which"] == "search"
    assert best(store)["rfz"] == {"error": "", "absent": ABSENT}


@pytest.mark.parametrize("damage", ["missing", "broken", "symlink", "outside"])
def test_bad_refine_result_does_not_spoil_search(tmp_path: Path, monkeypatch: pytest.MonkeyPatch, damage: str) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = winner_file(store)
    if damage == "missing":
        target.unlink()
    elif damage == "broken":
        target.write_text("{")
    elif damage == "symlink":
        saved = target.with_suffix(".saved")
        target.rename(saved)
        target.symlink_to(saved)
    else:
        path = store.path / "stage_one_refine.json"
        raw = json.loads(path.read_bytes())
        row = next(row for row in raw["results"] if row["refine_rank"] == 1)
        row["result_file"] = str(Path("..") / "outside.json")
        path.write_text(json.dumps(raw))
    _, _, default = best_versions(store.path)
    assert default == "refine"
    shown = best(store, "refine")
    for key in ("frequency", "rfz", "plan"):
        chart = shown[key]
        assert isinstance(chart, dict) and chart["error"].startswith("讀不到：")
    assert best(store, "search")["rfz"] == {"error": "", "absent": ABSENT}


@pytest.mark.parametrize("energy", [0., None, -1.])
def test_unavailable_energy_only_leaves_a_gap(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                           energy: float | None) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = winner_file(store)
    raw = json.loads(target.read_bytes())
    raw["curves"][0]["primary"]["fem_energy"][0] = energy
    target.write_text(json.dumps(raw))
    shown = best(store)["frequency"]
    assert isinstance(shown, dict) and shown["error"] == ""
    assert shown["curves"] == frequency_from_raw(json.dumps(raw))
    assert shown["curves"][0]["points"][0][1] is None


def test_cross_stage_rejection_and_cache_are_separate(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                                    best_result: SchemeResult) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = winner_file(store)
    cache = BestCache()
    assert cache.read(target, stage_one=True)["schema_version"] == "aosr.stage_one_result.v1"
    with pytest.raises(ValueError, match="結果檔版本不認得"):
        cache.read(target)
    target.write_text(best_result.model_dump_json())
    rejected = best(store, cache=cache)
    for key in ("frequency", "rfz", "plan"):
        assert rejected[key] == {"error": "讀不到：這是第一階段搜尋資料夾，結果檔卻是第二階段的格式"}
    assert cache.read(target)["schema_version"] == best_result.schema_version
    assert best(best_store(tmp_path / "second", best_result))["frequency"] != rejected["frequency"]


def test_reversed_curves_keep_speaker_roles(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = winner_file(store)
    raw = json.loads(target.read_bytes())
    raw["curves"].reverse()
    target.write_text(json.dumps(raw))
    shown = best(store)
    frequency, plan = shown["frequency"], shown["plan"]
    assert isinstance(frequency, dict) and isinstance(plan, dict)
    assert frequency["curves"] == frequency_from_raw(json.dumps(raw))
    assert shown["rfz"] == {"error": "", "absent": ABSENT}
    assert plan["error"] == ""


@pytest.mark.parametrize("damage", ["unknown", "missing_field", "invalid_score"])
def test_stage_one_schema_and_model_are_checked(tmp_path: Path, monkeypatch: pytest.MonkeyPatch, damage: str) -> None:
    store = _finished(tmp_path, monkeypatch)
    target = winner_file(store)
    raw = json.loads(target.read_bytes())
    if damage == "unknown":
        raw["schema_version"] = "unsupported"
    elif damage == "missing_field":
        del raw["wall_assumption_text"]
    else:
        raw["score"]["screening_total"] += 1
    target.write_text(json.dumps(raw))
    shown = best(store)
    for key in ("frequency", "rfz", "plan"):
        chart = shown[key]
        assert isinstance(chart, dict) and chart["error"].startswith("讀不到：")
        if damage == "unknown":
            assert shown[key] == {"error": "讀不到：結果檔版本不認得"}


def test_second_stage_folder_still_rejects_stage_one_result(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                                          best_result: SchemeResult) -> None:
    first = _finished(tmp_path / "first", monkeypatch)
    second = best_store(tmp_path / "second", best_result)
    second.candidate_path(0).write_bytes(winner_file(first).read_bytes())
    shown = best(second, "search")
    for key in ("frequency", "rfz", "plan"):
        assert shown[key] == {"error": "讀不到：結果檔版本不認得"}


def test_unmatched_speaker_only_spoils_frequency_projection(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    store = _finished(tmp_path, monkeypatch)
    raw = json.loads(winner_file(store).read_bytes())
    raw["curves"][0]["speaker_id"] = "unmatched"
    # 專考三圖的獨立邊界；檔案完整驗證由上一題守，這裡只替換快取回值。
    cache = BestCache()
    def read(path: Path, *, stage_one: bool = False) -> dict[str, object]:
        return {key: value for key, value in raw.items()}
    monkeypatch.setattr(cache, "read", read)
    shown = best(store, cache=cache)
    assert shown["frequency"] == {"error": "讀不到：主位報表與方案聲道對不上"}
    assert shown["rfz"] == {"error": "", "absent": ABSENT}
    plan = shown["plan"]
    assert isinstance(plan, dict) and plan["error"] == ""


def second_stage_case(tmp_path: Path, result: SchemeResult) -> SearchStore:
    # 耗時在造輸入時固定；真實時鐘的小數長度會改結果檔大小，連帶改版本字串。
    result = result.model_copy(update={"timings": Timings(solve_s=1., output_s=2., evaluate_s=3., total_s=6.)})
    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(uuid, "uuid4", lambda: uuid.UUID(int=1))
        store = best_store(tmp_path, result, "baseline")
    for path in store.path.rglob("*"):
        if path.is_file():
            os.utime(path, ns=(1700000000000000000, 1700000000000000000))
    return store


def second_stage_json(store: SearchStore, monkeypatch: pytest.MonkeyPatch) -> str:
    monkeypatch.setattr(time, "time", lambda: 1700000060.)
    monkeypatch.setattr(search_view, "datetime", UtcClock)
    monkeypatch.setattr(search_view, "folder_process", lambda path: search_view.Process(False, "沒有計算行程拿著這個資料夾"))
    opened, versions, default = best_versions(store.path)
    return json.dumps({"search": best(store, "search"), "refine": best(store, "refine"),
        "versions": [{"error": opened.error, "store": {key: str(value.relative_to(store.path.parent)) if isinstance(value, Path)
            else value.model_dump(mode="json") if hasattr(value, "model_dump") else {
                "physics_identity": value.physics_identity, "program_fingerprint": value.program_fingerprint,
                "purpose_settings": value.purpose_settings.model_dump(mode="json")}
            for key, value in vars(opened.value).items()} if opened.value else None},
            {key: value.model_dump() for key, value in versions.items()}, default],
        "view": search_view.build_search_view(store.path, server_physics="現在物理", server_program="現在程式").model_dump()},
        ensure_ascii=False, separators=(",", ":"))


def test_second_stage_json_is_byte_identical(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                           best_result: SchemeResult) -> None:
    store = second_stage_case(tmp_path, best_result)
    assert _masked(second_stage_json(store, monkeypatch)) == SECOND_STAGE


def _masked(text: str) -> str:
    """小數與結果檔大小遮成「#」：控制組結果由替身管線現算，雲端機器混用不比末位（新錄控制組不錄跨機器逐位的小數）。"""
    masked = FLOAT.sub("#", SIZE.sub(r"\1#\2", text))
    # 連續一串遮過的數字收成「#×個數」：點數照樣比，答案字面值不用逐點抄。
    return RUN.sub(lambda match: f"#×{match.group(0).count('#')}", masked)


FLOAT = re.compile(r"-?\d+\.\d+(?:[eE][-+]?\d+)?|-?\d+[eE][-+]?\d+")
# 版本字串「…:檔案時間:檔案大小:用途指紋」；檔案時間在輸入端固定，大小跟著小數的字數走。
SIZE = re.compile(r"(:1700000000000000000:)\d+(:)")
RUN = re.compile(r"#(?:,#)+")


